	 $$$TRACE(" Inside the method - parseExpiredFlag.... ")

	set arr = (consumedObj.%Get("data")).%Get("custom.expiredflag")
    $$$TRACE("  arr: "_arr _ " IsValidObject: " _$IsObject(arr))  	
    set index = 0
    if ( $IsObject(arr)){    	
  		Set arrIterObj = arr.%GetIterator()
  		while arrIterObj.%GetNext(.key, .value) {
	  		//$$$TRACE("arrIterObj:::  key: "_key_" Value: "_value)
	  		Set arrValObj = value.%GetIterator()	 
	    	while arrValObj.%GetNext(.key, .value) {
		  	   if (key = "custom.expiredflag"){		  		
		  			set result = $INCREMENT(index)		  		
		  			set hieDataDeathFlagObj = ##class(IHC.ITF.Service.HieDataExpiredFlag).%New()
		  			set hieDataDeathFlagObj.expiredFlag = value.expiredFlag
		  			$$$TRACE("custom.expiredflag:  "_value.expiredFlag)		    
	  			    do dataObj.hieDataExpiredFlag.SetAt(hieDataDeathFlagObj,index)
	  			}
	    	}		  
    	}
    }

